using BudgetSummaryFinal.Domain;
var tests = new (string, Action)[] { ("pipeline success", PipelineSuccess), ("configuration failures", ConfigurationFailures), ("Option present and absent", OptionCases), ("Map and Bind success", MapAndBindSuccess), ("failure propagation", FailurePropagation), ("extension selection", ExtensionSelection), ("extension snapshot", ExtensionSnapshot), ("variance report normal and no matches", VarianceReport), ("category report grouping totals", CategoryReport), ("reports empty and deterministic ties", EmptyAndTiedReports), ("curried partial scores differ", CurriedScores), ("lazy workflow defers then snapshots", LazyWorkflow), ("file resource released after success", FileReleasedAfterSuccess), ("file resource released after malformed", FileReleasedAfterMalformed), ("missing file boundary", MissingFile), ("malformed file boundary", MalformedFile), ("report export", ReportExport), ("native real call", NativeRealCall), ("native adapter failure", NativeAdapterFailure), ("complete native report workflow", CompleteWorkflow), ("complete failure workflow", CompleteFailureWorkflow) };
var failures = 0; foreach (var (name, test) in tests) { try { test(); Console.WriteLine($"PASS: {name}"); } catch (Exception error) { failures++; Console.WriteLine($"FAIL: {name} - {error.Message}"); } } Console.WriteLine($"{tests.Length - failures}/{tests.Length} tests passed."); return failures == 0 ? 0 : 1;
static void PipelineSuccess() { var summary = BudgetPipeline.ProduceSummary(Data.Records, BudgetPolicies.Standard, 100m); Equal(3, summary.Assessments.Count); Equal(1300m, summary.TotalPlanned); Equal(1, summary.OverBudgetCount); }
static void ConfigurationFailures() { Equal("InvalidMinimum", FailureValue(BudgetConfigurationFactory.CreateResult("standard", 99m)).Code); Equal("UnknownPolicy", FailureValue(BudgetConfigurationFactory.CreateResult("unknown", 100m)).Code); var state = BudgetSummaryWorkflow.Prepare(BudgetConfigurationFactory.Create("unknown", 100m)); True(BudgetSummaryWorkflow.Produce(state, Data.Records) is SummaryTransitionRejected); }
static void OptionCases() { var found = BudgetRecordLookup.FindById(Data.Records, "B005") as Some<BudgetRecord>; True(found is not null); Equal(false, found!.Value.IsApproved); True(BudgetRecordLookup.FindById(Data.Records, "NONE") is None<BudgetRecord>); }
static void MapAndBindSuccess() { Equal(101m, SuccessValue(Result.Ok(100m).Map(value => value + 1m))); Equal("B001", SuccessValue(Result.Ok("B001").Bind(id => BudgetRecordLookup.FindById(Data.Records, id).ToResult(new DomainError("RecordNotFound", "Not found")))).Id); }
static void FailurePropagation() { var called = false; Result<int> failure = Result.Fail<int>("InvalidMinimum", "bad minimum"); var afterMap = failure.Map(value => { called = true; return value + 1; }); var afterBind = failure.Bind(value => { called = true; return Result.Ok(value + 1); }); Equal("InvalidMinimum", FailureValue(afterMap).Code); Equal("InvalidMinimum", FailureValue(afterBind).Code); False(called); }
static void ExtensionSelection() { var selected = Data.Records.WhereApprovedAtLeast(100m).ToArray(); Equal(3, selected.Length); Equal("B001", selected[0].Id); }
static void ExtensionSnapshot() { var source = new[] { "one", "two" }; var snapshot = source.ToStableSnapshot(); source[0] = "changed"; Equal("one", snapshot[0]); }
static void VarianceReport() { var report = BudgetReports.CreateOverBudgetReport(Data.Records, 100m, BudgetPolicies.Standard, BudgetRiskScoring.StandardRiskScore); Equal(1, report.Count); Equal("B002", report[0].Id); Equal(15m, report[0].RiskScore); Equal(0, BudgetReports.CreateOverBudgetReport(Data.Records, 10_000m, BudgetPolicies.Standard, BudgetRiskScoring.StandardRiskScore).Count); }
static void CategoryReport() { var report = BudgetReports.CreateCategorySpendingReport(Data.Records); Equal(5, report.Count); var equipment = report.Single(x => x.Category == "Equipment"); Equal(1, equipment.RecordCount); Equal(1000m, equipment.TotalPlanned); Equal(1050m, equipment.TotalActual); }
static void EmptyAndTiedReports() { Equal(0, BudgetReports.CreateCategorySpendingReport(Array.Empty<BudgetRecord>()).Count); var records = new[] { new BudgetRecord("B2", "Beta", 100m, 120m, true), new BudgetRecord("B1", "Alpha", 100m, 120m, true) }; var variance = BudgetReports.CreateOverBudgetReport(records, 100m, BudgetPolicies.Strict, BudgetRiskScoring.StrictRiskScore); Equal("B1", variance[0].Id); Equal("B2", variance[1].Id); var categories = BudgetReports.CreateCategorySpendingReport(records); Equal("Alpha", categories[0].Category); Equal("Beta", categories[1].Category); }
static void CurriedScores() { var record = new BudgetRecord("R1", "Test", 100m, 110m, true); Equal(0m, BudgetRiskScoring.StandardRiskScore(record)); Equal(10m, BudgetRiskScoring.StrictRiskScore(record)); }
static void LazyWorkflow() { var visited = 0; IEnumerable<BudgetRecord> CountedSource() { foreach (var record in Data.Records) { visited++; yield return record; } } var lazy = BudgetLazyWorkflow.StreamEligibleRecords(CountedSource(), 100m); Equal(0, visited); var snapshot = lazy.ToStableSnapshot(); Equal(5, visited); Equal(3, snapshot.Count); var afterMaterialization = visited; Equal(3, snapshot.Count); Equal(afterMaterialization, visited); }
static void FileReleasedAfterSuccess() => WithTempFile(Data.Csv, path => { SuccessValue(BudgetDataBoundary.LoadRecords(path)); AssertCanRename(path); });
static void FileReleasedAfterMalformed() => WithTempFile("bad header", path => { Equal("MalformedCsv", FailureValue(BudgetDataBoundary.LoadRecords(path)).Code); AssertCanRename(path); });
static void MissingFile() { var path = Path.Combine(Path.GetTempPath(), $"budget-missing-{Guid.NewGuid():N}.csv"); Equal("FileNotFound", FailureValue(BudgetDataBoundary.LoadRecords(path)).Code); }
static void MalformedFile() => WithTempFile("bad header", path => Equal("MalformedCsv", FailureValue(BudgetDataBoundary.LoadRecords(path)).Code));
static void ReportExport() { var path = Path.Combine(Path.GetTempPath(), $"budget-export-{Guid.NewGuid():N}.csv"); try { var receipt = SuccessValue(BudgetDataBoundary.ExportCategoryReport(path, BudgetReports.CreateCategorySpendingReport(Data.Records))); Equal(5, receipt.CategoryCount); True(File.ReadAllText(path).Contains("Equipment,1,1000,1050", StringComparison.Ordinal)); } finally { if (File.Exists(path)) File.Delete(path); } }
static void NativeRealCall() => Equal(113, SuccessValue(new NativeBudgetMetrics().CalculateUtilizationPercent(100m, 113.99m)));
static void NativeAdapterFailure() => Equal("NativeLibraryUnavailable", FailureValue(new FailingNativeBudgetMetrics("Controlled native load failure.").CalculateUtilizationPercent(100m, 110m)).Code);
static void CompleteWorkflow() => WithTempFile(Data.Csv, path => { var report = SuccessValue(BudgetApplication.Run(path, "strict", 100m, "B005")); Equal("B005", report.FocusRecord.Id); Equal(108, report.NativeUtilizationPercent); Equal(3, report.OverBudgetReport.Count); Equal(5, report.CategorySpendingReport.Count); });
static void CompleteFailureWorkflow() => WithTempFile(Data.Csv, path => Equal("NativeLibraryUnavailable", FailureValue(BudgetApplication.Run(path, "standard", 100m, "B002", new FailingNativeBudgetMetrics("Controlled native load failure."))).Code));
static void AssertCanRename(string path) { var moved = path + ".moved"; File.Move(path, moved); File.Move(moved, path); }
static void WithTempFile(string content, Action<string> test) { var path = Path.Combine(Path.GetTempPath(), $"budget-test-{Guid.NewGuid():N}.csv"); try { File.WriteAllText(path, content); test(path); } finally { if (File.Exists(path)) File.Delete(path); if (File.Exists(path + ".moved")) File.Delete(path + ".moved"); } }
static T SuccessValue<T>(Result<T> result) => result is Success<T> success ? success.Value : throw new InvalidOperationException("Expected Success."); static DomainError FailureValue<T>(Result<T> result) => result is Failure<T> failure ? failure.Error : throw new InvalidOperationException("Expected Failure."); static void True(bool value) { if (!value) throw new InvalidOperationException("Expected true."); } static void False(bool value) { if (value) throw new InvalidOperationException("Expected false."); } static void Equal<T>(T expected, T actual) where T : IEquatable<T> { if (!expected.Equals(actual)) throw new InvalidOperationException($"Expected {expected}, actual {actual}."); }
static class Data { public const string Csv = "Id,Category,PlannedAmount,ActualAmount,IsApproved\nB001,Food,100,110,true\nB002,Transport,200,250,true\nB003,Training,90,80,true\nB004,Equipment,1000,1050,true\nB005,Marketing,500,400,false"; public static readonly BudgetRecord[] Records = [new("B001", "Food", 100m, 110m, true), new("B002", "Transport", 200m, 250m, true), new("B003", "Training", 90m, 80m, true), new("B004", "Equipment", 1000m, 1050m, true), new("B005", "Marketing", 500m, 400m, false)]; }
